'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v12.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v11c.css');
const meshCss=read('docs/scifi-ui/styles/formatx-core-mesh3d.css');
const apex=read('docs/scifi-ui/scripts/formatx-apex-native.js');
const voice=read('docs/scifi-ui/scripts/organism-voice-stability.js');
const interaction=read('docs/scifi-ui/scripts/organism-core-interaction.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');

assert.match(mapper,/fxApexSceneStability==='ready-v22'/,'v12 material mapper revision missing');
assert.match(mapper,/formatx-core-mesh3d-material-v12\.js\?v=20260809-reference-glass-v12/,'v12 material bootstrap missing');
assert.match(mapper,/formatx-core-mesh3d-v11\.js\?v=20260809-cinematic-mesh3d-v11/,'v11 true mesh bootstrap missing');
assert.match(mapper,/formatx-core-cinematic-kick-v11\.js\?v=20260809-cinematic-kick-v11b/,'frame-independent cinematic kick bootstrap missing');
assert.match(mapper,/formatx-core-fracture3d-v11\.js\?v=20260809-cinematic-fracture3d-v11/,'v11 fracture bootstrap missing');
assert.match(mapper,/formatx-core-cinematic-grade-v11c\.css\?v=20260809-reference-emissive-v1/,'reference grade bootstrap missing');
assert.match(mapper,/cinematic-reference-glass-true-mesh3d-v22/,'v12 reference glass visual marker missing');
assert.match(mapper,/fxCoreMaterialContract='reference-glass-v12'/,'v12 material contract missing');
assert.match(mapper,/if\(uScene<\.92\)return vec2\(10\.,1\.\)/,'legacy SDF MAG suppression missing');
assert.match(mapper,/retired-for-real-3d-reactor/,'screen-space reactor retirement missing');
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/,'mapper must not capture scrolling');

assert.match(material,/uniform float uAlpha,uTime,uHeart,uMode,uEnergy,uSurge,uSpeech/,'material shader identification missing');
assert.match(material,/float fres=pow\(1\.-ndv,1\.62\)/,'glass Fresnel missing');
assert.match(material,/float causticA=/,'cyan internal caustic A missing');
assert.match(material,/float causticB=/,'cyan internal caustic B missing');
assert.match(material,/float violetVein=/,'violet energy vein missing');
assert.match(material,/vec3\(\.20,1\.38,2\.30\)\*fres/,'strong cyan glass edge emission missing');
assert.match(material,/film\(c\*1\.42\)/,'glass film tone mapping exposure missing');
assert.match(material,/vec3 film\(vec3 x\)/,'exponential film tonemap missing');
assert.match(material,/fxCoreMeshMaterial='reference-glass-v12'/,'material applied marker missing');
assert.match(material,/fxCoreMeshMaterialPatch='applied'/,'material patch applied marker missing');
assert.doesNotMatch(material,/drawImage\s*\(|new Image\s*\(|background-image/i,'material must not be image-backed');

assert.match(mesh,/getContext\('webgl2'/,'WebGL2 mesh context missing');
assert.match(mesh,/depth:true/,'mesh depth buffer missing');
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/,'mesh depth testing missing');
assert.match(mesh,/gl\.enable\(gl\.CULL_FACE\)/,'mesh face culling missing');
assert.match(mesh,/gl\.cullFace\(gl\.FRONT\)/,'back-face glass pass missing');
assert.match(mesh,/gl\.cullFace\(gl\.BACK\)/,'front-face glass pass missing');
assert.match(mesh,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'mesh index buffer missing');
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangle rendering missing');
assert.match(mesh,/aPosition/,'vertex positions missing');
assert.match(mesh,/aNormal/,'vertex normals missing');
assert.match(mesh,/uProjection\*uView\*vec4\(p,1\.\)/,'perspective projection missing');
assert.match(mesh,/xs=\.82/,'horizontal reference proportion missing');
assert.match(mesh,/ys=1\.30/,'vertical reference proportion missing');
assert.match(mesh,/dep=\.36/,'real Z depth missing');
assert.match(mesh,/core=up\(sphere\(\.060\)\)/,'real reactor sphere missing');
assert.match(mesh,/up\(torus\(\.23,\.0055\)\)/,'inner reactor torus missing');
assert.match(mesh,/up\(torus\(\.34,\.005\)\)/,'middle reactor torus missing');
assert.match(mesh,/up\(torus\(\.47,\.0046\)\)/,'outer reactor torus missing');
assert.match(mesh,/hBeam=up\(box\(\.92,\.006,\.005\)\)/,'horizontal flare geometry missing');
assert.match(mesh,/vBeam=up\(box\(\.006,1\.05,\.005\)\)/,'vertical flare geometry missing');
assert.match(mesh,/window\.FormatXCoreCinematic=\{version:'film-reactive-v1'/,'cinematic state missing');
assert.match(mesh,/outerRot=.*midRot=.*innerRot=/s,'independent internal rotations missing');
assert.match(mesh,/reactorPulse=1\+heart\*/,'reactor heartbeat missing');
assert.match(mesh,/orbSpeed=\.010\+\.026\*cinematic\.energy/,'energy-driven orbit acceleration missing');
assert.match(mesh,/fxCoreMesh3d='ready-v11'/,'mesh ready marker missing');
assert.match(mesh,/fxCoreGeometry='indexed-triangle-mesh-v11'/,'indexed mesh marker missing');
assert.match(mesh,/fxCoreCinematic='film-reactive-v1'/,'cinematic marker missing');
assert.doesNotMatch(mesh,/drawImage\s*\(|new Image\s*\(|background-image/i,'MAG must not be image-backed');
assert.doesNotMatch(mesh,/THREE\b|three\.js|gsap/i,'third-party scene framework forbidden');

assert.match(kick,/fxCoreCinematicKick==='ready-v1'/,'immediate cinematic kick missing');
assert.match(kick,/formatx:organismcoreactivate.*\.60,1\.00,1600/s,'activation kick missing');
assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s,'response kick missing');
assert.match(kick,/formatx:organismspeechstart.*\.80,\.72,5000,1/s,'speech kick missing');
assert.match(kick,/frame-rate-independent-v1/,'frame-independent marker missing');

assert.match(fracture,/getContext\('webgl2'/,'fracture WebGL2 context missing');
assert.match(fracture,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'fracture index buffer missing');
assert.match(fracture,/gl\.drawElements\(gl\.LINES/,'fracture indexed GL_LINES missing');
assert.match(fracture,/window\.FormatXCoreCinematic/,'fracture must share cinematic state');
assert.match(fracture,/fxCoreFracture3d='ready-v11'/,'fracture ready marker missing');
assert.match(fracture,/fxCoreFractureBehavior='cinematic-reactive-v1'/,'fracture cinematic behavior missing');

assert.match(grade,/brightness\(1\.95\)/,'desktop emissive grade missing');
assert.match(grade,/saturate\(2\.15\)/,'desktop saturation grade missing');
assert.match(grade,/brightness\(2\.02\)/,'mobile emissive grade missing');
assert.match(grade,/saturate\(2\.20\)/,'mobile saturation grade missing');
assert.match(grade,/drop-shadow\(0 0 5px rgba\(72, 226, 255, 0\.20\)\)/,'cyan bloom missing');

assert.match(interaction,/formatx:organismcoreactivate/,'organism interaction event regressed');
assert.match(voice,/window\.visualViewport/,'dialogue viewport guard missing');
assert.match(voice,/keyboardInset/,'keyboard overlap guard missing');
assert.match(meshCss,/pointer-events: none/,'mesh must not capture input');
assert.match(meshCss,/height: 100dvh/,'dynamic viewport missing');
assert.match(apex,/quality: coarse\.matches \? 0\.82 : 0\.88/,'Apex background quality regressed');
assert.match(infinite,/const VERSION = 'seamless-v7'/,'seamless-v7 regressed');
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/,'native momentum regressed');
console.log('PASS: v12 uses a real indexed WebGL2 MAG with an actual cinematic glass fragment material, Fresnel/caustics/violet veins, film tonemap and reactive sci-fi behavior.');
